<script setup lang="ts">import type{TimingStatistics}from'../domain/types';defineProps<{seed:number;stats:TimingStatistics;events:readonly string[]}>()</script><template><details class="panel debug"><summary>Timing debug</summary><dl><dt>Session seed</dt><dd>{{seed}}</dd><dt>Samples</dt><dd>{{stats.count}}</dd><dt>P99</dt><dd>{{(stats.p99*1000).toFixed(2)}} ms</dd><dt>Max</dt><dd>{{(stats.max*1000).toFixed(2)}} ms</dd></dl><p v-for="event in events" :key="event">{{event}}</p></details></template>
